  Lemma ofi_prefix : forall (P : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem),
    0 <= P -> P + 80 < 2^64 ->
    evt rsegs (fun ms' => ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (P + 80)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (Z_to_bv 64 P_FIELDS_INSERT) fc None m (seg_rom rsegs))
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 P) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_ON_FIELD_IMPL) fc None m (seg_rom rsegs)).
  Proof.
    intros. unfold P_ON_FIELD_IMPL, P_FIELDS_INSERT. zstep. step. apply evt_done. reflexivity.
  Qed.

  Definition ofi_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (P f np vp ecA : Z) (name value : list byte) (E0 : ecv)
           (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo B : Z) (errv : word),
      a0 = Z_to_bv 64 P -> a1 = Z_to_bv 64 f -> a2 = Z_to_bv 64 np -> a3 = Z_to_bv 64 (zlength name) ->
      a4 = Z_to_bv 64 vp -> a5 = Z_to_bv 64 (zlength value) -> a6 = Z_to_bv 64 ecA ->
      FieldsC m (P + 80) S L ns ls em -> FieldsOwn LB em ->
      bytes_at rsegs m np name -> rclient_range LB (bv_unsigned sp) np (zlength name) ->
      bytes_at rsegs m vp value -> rclient_range LB (bv_unsigned sp) vp (zlength value) -> vp + zlength value < 2^64 ->
      zlength name <= 65533 -> zlength value <= 65533 -> 0 <= f < 2^16 ->
      rw_cells rsegs m ecA (ErrCodeCells E0) -> bv_unsigned sp <= ecA -> ecA + 24 <= B ->
      (ecA + 24 <= P + 80 \/ P + 128 <= ecA) -> (np + zlength name <= ecA \/ ecA + 24 <= np) -> (vp + zlength value <= ecA \/ ecA + 24 <= vp) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + (zlength name + zlength value + 67) <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> P + 128 <= B -> B <= 2^64 ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - INS_STACK -> bv_unsigned sp <= P ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (ins_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB (P + 80) f ecA name value L em lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_ON_FIELD_IMPL) fc None m (seg_rom rsegs)) mo).

